void transfer(Account& from, Account& to, long amt) {
  if (&from == &to) return;                 // locking the same mutex twice is UB
  std::scoped_lock lk(from.m, to.m);        // deadlock-avoidance algorithm
  if (from.balance < amt)
    throw std::runtime_error("insufficient funds");  // locks released by RAII
  from.balance -= amt;
  to.balance += amt;
}

